const TIP_ETIKET = { yuzuk:"Yüzük", kolye:"Kolye", kupe:"Küpe", bilezik:"Bilezik", bileklik:"Bileklik", pendant:"Pendant", set:"Set", diger:"" };
function tipEtiket(kat) {
  const k = String(kat||"").trim();
  if (!k) return "";
  const key = k.toLowerCase().replace(/ü/g,"u").replace(/ı/g,"i").replace(/ö/g,"o").replace(/ş/g,"s").replace(/ç/g,"c").replace(/ğ/g,"g");
  if (key in TIP_ETIKET) return TIP_ETIKET[key];
  return k.charAt(0).toUpperCase()+k.slice(1);
}

function gramDonustur(refGram, refAyar, hedefAyar, tasGram) {
  if (refAyar === hedefAyar) return refGram;
  // Yoğunluk bazlı dönüşüm (g/cm³) — sektör standardı
  const yogunluk = { "8K":11.0, "9K":11.3, "10K":11.6, "14K":13.4, "18K":15.5, "21K":17.0, "22K":17.7, "24K":19.3, "925":10.4 };
  const eskiY = yogunluk[refAyar] || 13.4;
  const yeniY = yogunluk[hedefAyar] || 13.4;
  // Taş gramını ayır (taş değişmez!)
  const tas = Number(tasGram) || 0;
  const madenGram = Math.max(0, Number(refGram) - tas);
  // Yoğunluk oranıyla maden gramını dönüştür
  const yeniMadenGram = madenGram * (yeniY / eskiY);
  // Taşı geri ekle
  return yeniMadenGram + tas;
}

// Çerçeve içindeki ürün fotoğrafının kenarları hafifçe solar → fotoğraf zemini ile çerçeve zemini arasındaki ince çizgi görünmez
const FOTO_KENAR_SOLUK = (() => { const g = "linear-gradient(to right,transparent,#000 7%,#000 93%,transparent),linear-gradient(to bottom,transparent,#000 7%,#000 93%,transparent)"; return { maskImage:g, WebkitMaskImage:g, maskComposite:"intersect", WebkitMaskComposite:"source-in" }; })();

// ═══ AYAR BAZLI İŞÇİLİK ÇÖZÜMÜ (10K / 14K / 18K ayrı fiyat) ═══
// Öncelik: Konfirmasyondaki elle giriş (o ayar için) > müşteri hafızası (o ayar için) > modelin o ayar için işçiliği > modelin genel işçiliği.
// Kayıt biçimi: { "10K": {iscilikDolar, iscilikBirim}, "14K": {...} }  (eski tek-fiyat biçimi { iscilikDolar, iscilikBirim } her ayara uygulanır — geriye uyum)
// Ayar bazlı GENEL STANDART işçilik (örn. tüm modellerde 10K = $3.25/gr). Modelin o ayar için kendi fiyatı varsa o geçerli; yoksa bu standart.
// Sadece yeni teklif/sipariş hesabında ve kart/form gösteriminde kullanılır — kayıtlı siparişler fiyatı kendi içinde taşıdığı için eskiler değişmez.
const ISCILIK_STANDART_VARSAYILAN = { "10K": { dolar: 3.25, birim: "dolar" } };
let ISCILIK_STANDART = ISCILIK_STANDART_VARSAYILAN;
function setIscilikStandart(o) { ISCILIK_STANDART = (o && typeof o === "object") ? o : ISCILIK_STANDART_VARSAYILAN; }
function iscilikStandartUygula(m) {
  const ek = {};
  Object.entries(ISCILIK_STANDART || {}).forEach(([ay, v]) => { if (!(m.iscilikAyarlar || {})[ay] && v && v.dolar !== "" && v.dolar !== undefined) ek[ay] = { dolar: Number(v.dolar) || 0, birim: v.birim || "dolar" }; });
  return Object.keys(ek).length ? { ...m, iscilikAyarlar: { ...(m.iscilikAyarlar || {}), ...ek } } : m;
}
function iscilikOvrBul(kayit, ayar) {
  if (!kayit || typeof kayit !== "object") return null;
  if (kayit.iscilikDolar !== undefined) return kayit; // eski biçim
  const v = kayit[ayar];
  return (v && v.iscilikDolar !== undefined) ? v : null;
}
function iscilikCoz(m, ayar, konfKayit, hafizaKayit) {
  const o = iscilikOvrBul(konfKayit, ayar);
  if (o) return { dolar: o.iscilikDolar, birim: o.iscilikBirim || "dolar", kaynak: "konf" };
  const h = iscilikOvrBul(hafizaKayit, ayar);
  if (h) return { dolar: h.iscilikDolar, birim: h.iscilikBirim || "dolar", kaynak: "hafiza" };
  const ma = (m.iscilikAyarlar || {})[ayar];
  if (ma) return { dolar: Number(ma.dolar) || 0, birim: ma.birim || "dolar", kaynak: "model" };
  const gs = (ISCILIK_STANDART || {})[ayar];
  if (gs && gs.dolar !== "" && gs.dolar !== undefined) return { dolar: Number(gs.dolar) || 0, birim: gs.birim || "dolar", kaynak: "standart" };
  return { dolar: m.iscilikDolar, birim: m.iscilikBirim || "dolar", kaynak: "model" };
}
// hesapla() ayar bazlı işçiliği (iscilikAyarlar) genel işçiliğe tercih ettiği için, seçilen ayarın çözümlenmiş fiyatı HEM üst alana HEM iscilikAyarlar[ayar]'a yazılır
// (böylece ekran, toplamlar, kayıtlı sipariş ve PDF hepsi aynı fiyatı kullanır).
function iscilikliModel(m, ayar, konfKayit, hafizaKayit) {
  const c = iscilikCoz(m, ayar, konfKayit, hafizaKayit);
  return { ...m, iscilikDolar: c.dolar, iscilikBirim: c.birim, iscilikAyarlar: { ...(m.iscilikAyarlar || {}), [ayar]: { dolar: c.dolar, birim: c.birim } } };
}

// ═══ HESAPLAMA — Tüm sonuçlar HAS GRAM cinsinden ═══
// altinKgUSD: kg başına dolar (örn: 96000)
// hasGramUSD = altinKgUSD / 1000
// İşçilik has = (mamulGr × iscilikDolarGr) / hasGramUSD
// Taş has    = tasGr × ayarOran
// Maliyet has = mamulGr × maliyetMly (0.25)
// Ek maliyet has = ekMaliyetUSD / hasGramUSD
// Kâr has = Taş has + İşçilik has - Maliyet has - Ek maliyet has
function hesapla(m, secilenAyar, altinKgUSD, varsayilanMly) {
  const refAyar    = m.refAyar || "14K";
  const refGram    = Number(m.gram) || 0;
  const tasGram    = Number(m.tasGram) || 0;
  const aktifAyar  = secilenAyar || refAyar;
  const mamulGram  = gramDonustur(refGram, refAyar, aktifAyar, tasGram);
  const ayarOran   = (AYARLAR.find(a => a.id === aktifAyar) || { o: 0.585 }).o;
  const malMly     = Number(m.madenCarpan) || Number(varsayilanMly) || 0.030;
  const hasGramUSD = altinKgUSD > 0 ? altinKgUSD / 1000 : 0;

  // Taş has gram — seçilen ayar oranıyla çarpılır (14K→0.585, 10K→0.417 vs.)
  const tasHas = tasGram * ayarOran;

  // İşçilik — ayar bazlı fallback: seçilen ayar → girilmişse o, yoksa varsayılan
  const iscilikAyarlar = m.iscilikAyarlar || {};
  const ayarIscilik = (iscilikAyarlar[aktifAyar] && iscilikAyarlar[aktifAyar].dolar !== "" && iscilikAyarlar[aktifAyar].dolar != null) ? iscilikAyarlar[aktifAyar] : undefined; // boş (henüz değer girilmemiş) ayar satırı işçiliği 0'lamasın
  const iscilikDolarGr = ayarIscilik ? (Number(ayarIscilik.dolar) || 0) : (Number(m.iscilikDolar) || 0);
  const iscilikBirimKullan = ayarIscilik ? (ayarIscilik.birim || "dolar") : (m.iscilikBirim || "dolar");
  let iscilikHas = 0;
  let iscilikUSD = 0;
  if (iscilikBirimKullan === "milyem") {
    // milyem/gr → has gram doğrudan
    iscilikHas = mamulGram * iscilikDolarGr;
    iscilikUSD = iscilikHas * hasGramUSD;
  } else {
    // $/gr
    iscilikUSD = mamulGram * iscilikDolarGr;
    iscilikHas = hasGramUSD > 0 ? iscilikUSD / hasGramUSD : 0;
  }

  // Maliyet has gram
  const maliyetHas = mamulGram * malMly;

  // Ek maliyet has gram (USD olarak girilir)
  const ekMaliyetUSD = Number(m.ekMaliyet) || 0;
  const ekMaliyetHas = hasGramUSD > 0 ? ekMaliyetUSD / hasGramUSD : 0;

  // Toplam gelir has
  const gelirHas = tasHas + iscilikHas;
  // Toplam maliyet has
  const topMaliyetHas = maliyetHas + ekMaliyetHas;
  // Kâr has
  // Taş listesinde satır bazında girilen "kârdan düş (gr)" (yay, cam vb.): malın gramı DEĞİŞMEZ, gram × ayar oranı (has) kârdan düşer
  const tasKesinti = (Number(m.tasKarDus) || 0) * ayarOran;
  const karHas = gelirHas - topMaliyetHas - tasKesinti;
  const karUSD = karHas * hasGramUSD;
  // Karlılık milyem/gr = karHas / mamulGram
  const karMly = mamulGram > 0 ? karHas / mamulGram : 0;
  const karUyari = karMly < MIN_MLY && mamulGram > 0;

  // ═══ GÜMÜŞ (925) ÖZEL MANTIK ═══
  // Gümüşte altın karlılığı (mly/gr) anlamsız. Sadece işçilik hesaplanır.
  // İşçilik = toplam gümüş gramı (mamul zaten taşı içeriyor) × gram başı işçilik ($/gr)
  const gumusMu = aktifAyar === "925";
  let gumusIscilikGr = 0;   // $/gr
  let gumusIscilikTop = 0;  // toplam $
  if (gumusMu) {
    // İşçilik $/gr olarak alınır (milyem girilmişse de $/gr'a çevir — gümüşte milyem anlamsız)
    gumusIscilikGr = iscilikBirimKullan === "milyem"
      ? (hasGramUSD > 0 ? iscilikDolarGr * hasGramUSD : iscilikDolarGr) // milyem→$ kaba çevrim
      : iscilikDolarGr;
    gumusIscilikTop = mamulGram * gumusIscilikGr;
  }

  return {
    mamulGram, tasKesinti, aktifAyar, ayarOran,
    tasHas, iscilikUSD, iscilikHas,
    maliyetHas, ekMaliyetUSD, ekMaliyetHas,
    gelirHas, topMaliyetHas,
    karHas, karUSD, karMly, karUyari,
    hasGramUSD,
    gumusMu, gumusIscilikGr, gumusIscilikTop,
  };
}

// ═══ 14K KÂRINI KORUYAN HEDEF FİYAT ═══
// madenCarpan = MALİYET milyemi. Kâr = gelirHas(taş+işçilik) - maliyetHas.
// Taşlı üründe düşük ayarda taş has değer kaybeder → aynı kârı korumak için
// müşteriye daha yüksek fiyat gerekir. Bu fonksiyon o hedef fiyatı (has) verir.
// Dönüş: { ref14Kar, aktifKarHas, hedefSatisHas, aktifSatisHas, ekHas, farkli }
function karKoruyanFiyat(m, aktifAyar, altinKgUSD, varsayilanMly) {
  const tasGram = Number(m.tasGram) || 0;
  if (tasGram <= 0) return null; // taşsızda telafiye gerek yok
  const ref14 = hesapla({ ...m }, "14K", altinKgUSD, varsayilanMly);
  const aktif = hesapla({ ...m }, aktifAyar, altinKgUSD, varsayilanMly);
  if (aktif.mamulGram <= 0) return null;
  const ref14Kar = ref14.karHas;         // 14K'da korunacak kâr (has)
  const aktifKarHas = aktif.karHas;      // aktif ayarda mevcut kâr (has)
  // Aktif ayarda satış = gelir (taş+işçilik). Kârı 14K'ya eşitlemek için gereken ek:
  const ekHas = ref14Kar - aktifKarHas;  // pozitifse (10K) fiyat artmalı
  const aktifSatisHas = aktif.gelirHas;  // şu anki satış karşılığı (has)
  const hedefSatisHas = aktifSatisHas + ekHas;
  return {
    ref14Kar, aktifKarHas,
    aktifSatisHas, hedefSatisHas, ekHas,
    aktifMamul: aktif.mamulGram,
    hedefMlyGr: aktif.mamulGram > 0 ? hedefSatisHas / aktif.mamulGram : 0,
    farkli: Math.abs(ekHas) > 0.0005,
  };
}

// ═══ AYAR KARŞILAŞTIRMA — aynı ürün 10K / 14K / 18K'da (hem model formunda hem ürün kartında kullanılır) ═══
// Taş gramı sabit kalır; sadece maden gramı ayarın yoğunluğuyla ölçeklenir. Kâr HAS cinsinden 14K'ya göre karşılaştırılır.
function ayarKarsilastir(m0, altinKgUSD, mc, ayarlar) {
  const m = iscilikStandartUygula(m0); // kendi 10K fiyatı olmayan modelde genel standart işçilik
  const tl = Number(m.tasGram) || 0;
  const rows = (ayarlar || ["10K", "14K", "18K"]).map(ay => {
    const h = hesapla(m, ay, altinKgUSD, mc);
    const maden = Math.max(0, h.mamulGram - tl);
    return { ay, h, maden, tl, adetMaden: maden > 0 ? 1000 / maden : 0, adetMamul: h.mamulGram > 0 ? 1000 / h.mamulGram : 0 };
  });
  const ref = rows.find(r => r.ay === "14K");
  rows.forEach(r => { r.fark = ref ? r.h.karHas - ref.h.karHas : 0; r.kayip = r.fark < -0.0005; });
  return rows;
}

// ═══ ŞİRKET (MULTI-COMPANY) ═══
// Aktif şirketin Supabase anahtar öneki. MSK = "" (mevcut veriler korunur), BSP = "bsp2_".
// Şirket bağımsız anahtarlar (önek almayan): şifre, ayarlar gibi global olanlar burada listelenir.
let AKTIF_SIRKET_ONEK = (() => {
  try {
    // Eski şirketler-arası karışık cache'i temizle (bir kereye mahsus)
    localStorage.removeItem("atolye_full_cache");
  } catch {}
  try { return localStorage.getItem("atolye_sirket_onek") || ""; } catch { return ""; }
})();
function setSirketOnek(onek) {
  AKTIF_SIRKET_ONEK = onek || "";
  try { localStorage.setItem("atolye_sirket_onek", AKTIF_SIRKET_ONEK); } catch {}
}
// ═══ BSP (mum satışı) — sadeleştirilmiş sipariş durumları (mevcut durum kimlikleriyle eşleşir) ═══
const BSP_DURUM_IDS = ["baslanmadi","dokum","teslim"];
const BSP_DURUM_AD  = { baslanmadi:"İşleme alındı", cizimde:"Çiziliyor", dokum:"Makineye atıldı", teslim:"Müşteriye teslim edildi" };
function durumEtiket(d) { return (AKTIF_SIRKET_ONEK === "bsp2_" && BSP_DURUM_AD[d.id]) ? BSP_DURUM_AD[d.id] : d.l; }
function durumSecenekleri() { const l = DURUMLAR.filter(d => d.id !== "hurda" && d.id !== "cizimde"); return AKTIF_SIRKET_ONEK === "bsp2_" ? l.filter(d => BSP_DURUM_IDS.includes(d.id)) : l; }
// Bu anahtarlar şirketten bağımsız (önek ALMAZ) — her iki şirkette ortak kalır
const SIRKET_BAGIMSIZ = ["atolye_sifre"];
function sirketAnahtar(k) {
  if (!AKTIF_SIRKET_ONEK) return k;            // MSK → değişiklik yok
  if (SIRKET_BAGIMSIZ.includes(k)) return k;   // global anahtar
  return AKTIF_SIRKET_ONEK + k;                // BSP → "bsp2_" öneki
}

async function ld(k, f) { try { const r = await dbLoad(sirketAnahtar(k), f); return r ?? f; } catch { return f; } }
async function sv(k, d) { try { await dbSave(sirketAnahtar(k), d); } catch(e) { console.error("sv error:", e); } }

// Canvas şeffaf piksel içeriyorsa #f3f3f3 zemine oturtur (temiz foto sayılır), çıktı JPEG
function canvasCikti(c, kalite) {
  _sonYuklemeSaydam = false;
  try {
    const k = document.createElement("canvas"); k.width = 48; k.height = 48;
    const kx = k.getContext("2d"); kx.drawImage(c, 0, 0, 48, 48);
    const d = kx.getImageData(0, 0, 48, 48).data; let say = 0;
    for (let i = 3; i < d.length; i += 4) { if (d[i] < 250) say++; }
    if (say > 48 * 48 * 0.02) {
      const o = document.createElement("canvas"); o.width = c.width; o.height = c.height;
      const ox = o.getContext("2d"); ox.fillStyle = "#f3f3f3"; ox.fillRect(0, 0, o.width, o.height); ox.drawImage(c, 0, 0);
      _sonYuklemeSaydam = true;
      return o.toDataURL("image/jpeg", kalite);
    }
  } catch (e) {}
  return c.toDataURL("image/jpeg", kalite);
}

function resizeImg(file) {
  return new Promise(resolve => {
    const rd = new FileReader();
    rd.onload = e => {
      const img = new Image();
      img.onload = () => {
        const c = document.createElement("canvas");
        let w = img.width, h = img.height;
        if (w > 2000) { h = Math.round(h * 2000 / w); w = 2000; }
        if (h > 2000) { w = Math.round(w * 2000 / h); h = 2000; }
        c.width = w; c.height = h;
        const ctx = c.getContext("2d");
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = "high";
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvasCikti(c, 0.94));
      };
      img.src = e.target.result;
    };
    rd.readAsDataURL(file);
  });
}

// Bir data-URL fotoğrafın (x,y,w,h) — 0..1 fraksiyon — bölgesini kırpıp aynı kalite standardıyla döndürür
// Detay lensi için <img> stili — GERÇEK img elemanı + yüzde bazlı width/height/left/top.
// (CSS background-position yerine bunu kullanıyoruz: matematik burada tam kontrolümüzde,
// hangi tarayıcıda da aynı davranır.) zoom = görüntünün konteynere göre % büyüklüğü (örn 800 = 8x).
function lensImgStil(cx, cy, zoom) {
  const z = zoom + "%";
  return {
    position: "absolute",
    width: z, height: z, maxWidth: "none", maxHeight: "none",
    left: (50 - (cx||0.5) * zoom) + "%",
    top: (50 - (cy||0.5) * zoom) + "%",
  };
}

function cropFromDataURL(src, kirp) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const sx = Math.round(kirp.x * img.naturalWidth);
      const sy = Math.round(kirp.y * img.naturalHeight);
      const sw = Math.max(1, Math.round(kirp.w * img.naturalWidth));
      const sh = Math.max(1, Math.round(kirp.h * img.naturalHeight));
      let w = sw, h = sh;
      if (w > 2000) { h = Math.round(h * 2000 / w); w = 2000; }
      if (h > 2000) { w = Math.round(w * 2000 / h); h = 2000; }
      const c = document.createElement("canvas");
      c.width = w; c.height = h;
      const ctx = c.getContext("2d");
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(img, sx, sy, sw, sh, 0, 0, w, h);
      resolve(canvasCikti(c, 0.94));
    };
    img.onerror = reject;
    img.src = src;
  });
}

// ═══ FOTO KIRPMA ARACI — sürükle/boyutlandır, kırp ═══
function FotoKirpModal({ src, onConfirm, onCancel }) {
  const kutuRef = useRef(null);
  const [oran, setOran] = useState(4/3);
  const [kirp, setKirp] = useState({ x:0.05, y:0.05, w:0.9, h:0.9 });
  const [isliyor, setIsliyor] = useState(false);

  const suruklemeBasla = (e, tip) => {
    e.preventDefault(); e.stopPropagation();
    const el = e.currentTarget;
    try { el.setPointerCapture(e.pointerId); } catch {}
    const kutu = kutuRef.current;
    const basKirp = { ...kirp };
    const r0 = kutu.getBoundingClientRect();
    const basX = (e.clientX - r0.left) / r0.width, basY = (e.clientY - r0.top) / r0.height;
    const hareket = (ev) => {
      const r = kutu.getBoundingClientRect();
      const dx = (ev.clientX - r.left) / r.width - basX;
      const dy = (ev.clientY - r.top) / r.height - basY;
      setKirp(prev => {
        let { x, y, w, h } = basKirp;
        const MIN = 0.08;
        if (tip === "move") {
          x = Math.min(1-w, Math.max(0, basKirp.x + dx));
          y = Math.min(1-h, Math.max(0, basKirp.y + dy));
        } else if (tip === "se") { w = Math.min(1-x, Math.max(MIN, basKirp.w + dx)); h = Math.min(1-y, Math.max(MIN, basKirp.h + dy)); }
        else if (tip === "sw") { const nw = Math.min(basKirp.x+basKirp.w, Math.max(MIN, basKirp.w - dx)); x = basKirp.x + basKirp.w - nw; w = nw; h = Math.min(1-y, Math.max(MIN, basKirp.h + dy)); }
        else if (tip === "ne") { w = Math.min(1-x, Math.max(MIN, basKirp.w + dx)); const nh = Math.min(basKirp.y+basKirp.h, Math.max(MIN, basKirp.h - dy)); y = basKirp.y + basKirp.h - nh; h = nh; }
        else if (tip === "nw") { const nw = Math.min(basKirp.x+basKirp.w, Math.max(MIN, basKirp.w - dx)); x = basKirp.x + basKirp.w - nw; w = nw; const nh = Math.min(basKirp.y+basKirp.h, Math.max(MIN, basKirp.h - dy)); y = basKirp.y + basKirp.h - nh; h = nh; }
        return { x, y, w, h };
      });
    };
    const birak = () => { el.removeEventListener("pointermove", hareket); el.removeEventListener("pointerup", birak); };
    el.addEventListener("pointermove", hareket);
    el.addEventListener("pointerup", birak);
  };

  const onaylaKirp = async () => {
    setIsliyor(true);
    try { onConfirm(await cropFromDataURL(src, kirp)); } finally { setIsliyor(false); }
  };

  return (
    <div onClick={onCancel} style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.82)", zIndex:200, display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
      <div onClick={e=>e.stopPropagation()} style={{ background:"#1c1c1e", borderRadius:16, maxWidth:560, width:"100%", padding:20 }}>
        <div style={{ fontSize:15, fontWeight:600, color:"#f5f5f7", marginBottom:12 }}>Fotoğrafı Kırp</div>
        <div ref={kutuRef} style={{ position:"relative", width:"100%", maxHeight:"60vh", background:"#000", borderRadius:10, overflow:"hidden", touchAction:"none" }}>
          <img src={src} alt="" onLoad={e=>setOran((e.target.naturalWidth||4)/(e.target.naturalHeight||3))} style={{ width:"100%", display:"block", userSelect:"none" }} draggable={false}/>
          {/* Karartma — kırpma alanı DIŞI */}
          <div style={{ position:"absolute", inset:0, background:"rgba(0,0,0,0.55)", clipPath:`polygon(0 0,100% 0,100% 100%,0 100%,0 ${kirp.y*100}%,${kirp.x*100}% ${kirp.y*100}%,${kirp.x*100}% ${(kirp.y+kirp.h)*100}%,${(kirp.x+kirp.w)*100}% ${(kirp.y+kirp.h)*100}%,${(kirp.x+kirp.w)*100}% ${kirp.y*100}%,0 ${kirp.y*100}%)`, pointerEvents:"none" }}/>
          {/* Kırpma çerçevesi — sürükle taşı */}
          <div onPointerDown={e=>suruklemeBasla(e,"move")}
            style={{ position:"absolute", left:(kirp.x*100)+"%", top:(kirp.y*100)+"%", width:(kirp.w*100)+"%", height:(kirp.h*100)+"%", border:"2px solid #fff", boxShadow:"0 0 0 1px rgba(0,0,0,0.4)", cursor:"move" }}>
            {[["nw",-7,-7],["ne","calc(100% - 7px)",-7],["sw",-7,"calc(100% - 7px)"],["se","calc(100% - 7px)","calc(100% - 7px)"]].map(([tip,l,t]) => (
              <div key={tip} onPointerDown={e=>suruklemeBasla(e,tip)}
                style={{ position:"absolute", left:l, top:t, width:14, height:14, borderRadius:"50%", background:"#fff", border:"2px solid var(--vurgu)", cursor:tip+"-resize" }}/>
            ))}
          </div>
        </div>
        <div style={{ fontSize:10, color:"#86868b", margin:"10px 0 16px" }}>Köşelerden boyutlandırın, içinden sürükleyerek taşıyın.</div>
        <div style={{ display:"flex", gap:8 }}>
          <button onClick={onCancel} style={{ flex:1, background:"rgba(255,255,255,0.08)", border:"none", borderRadius:10, padding:"12px", color:"#f5f5f7", fontSize:13, fontWeight:600, cursor:"pointer" }}>Vazgeç</button>
          <button onClick={onaylaKirp} disabled={isliyor} style={{ flex:2, background: isliyor?"rgba(255,255,255,0.15)":"var(--vurgu)", border:"none", borderRadius:10, padding:"12px", color:"#fff", fontSize:13, fontWeight:600, cursor: isliyor?"default":"pointer" }}>
            {isliyor ? "İşleniyor..." : "✂️ Kırp ve Kullan"}
          </button>
        </div>
      </div>
    </div>
  );
}

// ═══ ARKA PLAN SİLME (tarayıcıda yapay zekâ) + GÖLGE + İŞARETLE + YAKINLAŞTIR/UZAKLAŞTIR ═══
// Temiz (arka planı silinmiş / şeffaf yüklenmiş) fotoğraflar — model kartında yeşil nokta için
const _temizFotolar = new Set();
let _fotoGecmis = [];           // ↩ Geri al — bu oturumda önceki fotoğraflar
let _koruMaske = null;          // { foto, canvas } — AI'dan korunacak bölgeler
let _aiCihaz = null;
let _imglyModul = null;
let _sonYuklemeSaydam = false;
function fotoTemizTasi(eski, yeni) { if (eski && yeni && _temizFotolar.has(eski)) _temizFotolar.add(yeni); return yeni; }

async function aiModulYukle() {
  if (_imglyModul) return _imglyModul;
  const adres = "https://esm.sh/@imgly/background-removal@1.5.8";
  _imglyModul = await import(/* @vite-ignore */ adres);
  return _imglyModul;
}
function resimYukle(src) {
  return new Promise((res, rej) => { const i = new Image(); i.crossOrigin = "anonymous"; i.onload = () => res(i); i.onerror = () => rej(new Error("Fotoğraf okunamadı")); i.src = src; });
}
// Kesilmiş (şeffaf) görüntüyü #f3f3f3 zemine koyar; isteğe bağlı yumuşak zemin gölgesi ekler
async function kesikGolgeli(silCanvas, golge) {
  const W = silCanvas.width, H = silCanvas.height;
  const sx = silCanvas.getContext("2d").getImageData(0, 0, W, H).data;
  let x0 = W, x1 = 0, y0 = H, y1 = 0;
  for (let y = 0; y < H; y += 2) for (let x = 0; x < W; x += 2) { if (sx[(y * W + x) * 4 + 3] > 128) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; } }
  const out = document.createElement("canvas"); out.width = W; out.height = H;
  const ctx = out.getContext("2d"); ctx.fillStyle = "#f3f3f3"; ctx.fillRect(0, 0, W, H);
  if (golge && x1 > x0 && y1 > y0) {
    const bw = x1 - x0, bh = y1 - y0, serit = bh * 0.30, yassi = Math.max(4, bh * 0.06);
    const sil = document.createElement("canvas"); sil.width = W; sil.height = H;
    const sc = sil.getContext("2d"); sc.drawImage(silCanvas, 0, 0); sc.globalCompositeOperation = "source-in"; sc.fillStyle = "#000"; sc.fillRect(0, 0, W, H);
    ctx.save(); ctx.filter = "blur(" + Math.max(3, Math.round(bw * 0.02)) + "px)"; ctx.globalAlpha = 0.145;
    ctx.drawImage(sil, x0, y1 - serit, bw, serit, x0 + bw * 0.025, y1 - yassi * 0.55, bw, yassi);
    ctx.restore();
  }
  ctx.drawImage(silCanvas, 0, 0);
  return out.toDataURL("image/jpeg", 0.97);
}
async function arkaPlanSilAI(src, ilerle, golge, koru) {
  const mod = await aiModulYukle();
  const fn = mod.removeBackground || mod.default;
  const blob = await (await fetch(src)).blob();
  const sec = (device) => ({ model: "isnet_fp16", device, output: { format: "image/png", type: "foreground" }, progress: (k, a, t) => { try { ilerle && ilerle(k, a, t); } catch (e) {} } });
  let sonuc;
  const once = _aiCihaz || (typeof navigator !== "undefined" && navigator.gpu ? "gpu" : "cpu");
  try { sonuc = await fn(blob, sec(once)); _aiCihaz = once; }
  catch (e) { if (once === "gpu") { sonuc = await fn(blob, sec("cpu")); _aiCihaz = "cpu"; } else throw e; }
  const img = await resimYukle(URL.createObjectURL(sonuc));
  const c = document.createElement("canvas"); c.width = img.naturalWidth; c.height = img.naturalHeight;
  const cx = c.getContext("2d"); cx.drawImage(img, 0, 0);
  if (koru) {
    // Korunan bölgeler (beyaz/inci taşlar): orijinal pikselleri kesimin altına karıştır
    const orj = await resimYukle(src);
    const mk = document.createElement("canvas"); mk.width = c.width; mk.height = c.height;
    const mx = mk.getContext("2d"); mx.filter = "blur(2px)"; mx.drawImage(koru, 0, 0, c.width, c.height);
    const mp = mx.getImageData(0, 0, c.width, c.height).data;
    const ot = document.createElement("canvas"); ot.width = c.width; ot.height = c.height;
    const ox = ot.getContext("2d"); ox.drawImage(orj, 0, 0, c.width, c.height);
    const od = ox.getImageData(0, 0, c.width, c.height);
    for (let i = 0; i < mp.length; i += 4) od.data[i + 3] = mp[i + 3];
    ox.putImageData(od, 0, 0);
    cx.globalCompositeOperation = "destination-over"; cx.drawImage(ot, 0, 0); cx.globalCompositeOperation = "source-over";
  }
  return kesikGolgeli(c, golge);
}
// Ürünü kare içinde büyüt/küçült (faktor>1 yakınlaştır, <1 uzaklaştır). Zemin: köşe rengi
async function fotoZoomla(src, faktor) {
  const img = await resimYukle(src);
  const W = img.naturalWidth, H = img.naturalHeight;
  const c = document.createElement("canvas"); c.width = W; c.height = H;
  const cx = c.getContext("2d");
  const k = document.createElement("canvas"); k.width = 1; k.height = 1;
  k.getContext("2d").drawImage(img, 0, 0, 4, 4, 0, 0, 1, 1);
  const p = k.getContext("2d").getImageData(0, 0, 1, 1).data;
  cx.fillStyle = "rgb(" + p[0] + "," + p[1] + "," + p[2] + ")"; cx.fillRect(0, 0, W, H);
  const w = W * faktor, h = H * faktor;
  cx.imageSmoothingQuality = "high"; cx.drawImage(img, (W - w) / 2, (H - h) / 2, w, h);
  return c.toDataURL("image/jpeg", 0.95);
}
async function fotoCevir(src) {
  const img = await resimYukle(src);
  const c = document.createElement("canvas"); c.width = img.naturalWidth; c.height = img.naturalHeight;
  const cx = c.getContext("2d"); cx.translate(c.width, 0); cx.scale(-1, 1); cx.drawImage(img, 0, 0);
  return c.toDataURL("image/jpeg", 0.95);
}

// 🖌 İşaretle — AI'ın silmemesi gereken bölgeleri (beyaz/inci taşlar) fırçayla boya
function FotoKoruModal({ src, baslangic, onTamam, onIptal }) {
  const cvRef = useRef(null), imgRef = useRef(null);
  const [kalin, setKalin] = useState(28);
  const [silgi, setSilgi] = useState(false);
  const cizili = useRef(false);
  useEffect(() => {
    const i = new Image(); i.onload = () => {
      const c = cvRef.current; if (!c) return;
      c.width = i.naturalWidth; c.height = i.naturalHeight; imgRef.current = i;
      if (baslangic) c.getContext("2d").drawImage(baslangic, 0, 0, c.width, c.height);
    }; i.src = src;
  }, [src, baslangic]);
  const nokta = (e) => {
    const c = cvRef.current, r = c.getBoundingClientRect();
    const x = (e.clientX - r.left) * c.width / r.width, y = (e.clientY - r.top) * c.height / r.height;
    const ctx = c.getContext("2d"); const rad = kalin * c.width / 800;
    ctx.globalCompositeOperation = silgi ? "destination-out" : "source-over";
    ctx.fillStyle = "#ff2d7a"; ctx.beginPath(); ctx.arc(x, y, rad, 0, Math.PI * 2); ctx.fill();
  };
  const bos = () => { const c = cvRef.current; const d = c.getContext("2d").getImageData(0, 0, c.width, c.height).data; for (let i = 3; i < d.length; i += 16) if (d[i] > 0) return false; return true; };
  return (
    <div onClick={onIptal} style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.85)", zIndex:210, display:"flex", alignItems:"center", justifyContent:"center", padding:16 }}>
      <div onClick={e=>e.stopPropagation()} style={{ background:"#1c1c1e", borderRadius:16, maxWidth:640, width:"100%", padding:18 }}>
        <div style={{ fontSize:15, fontWeight:600, color:"#f5f5f7", marginBottom:4 }}>🖌 Korunacak bölgeleri işaretle</div>
        <div style={{ fontSize:11, color:"#86868b", marginBottom:10 }}>Beyaz/inci taşlar gibi yapay zekânın silmesini istemediğin yerleri boya. Sonra ✨ Arka planı sil.</div>
        <div style={{ position:"relative", width:"100%", background:"#000", borderRadius:10, overflow:"hidden", touchAction:"none" }}>
          <img src={src} alt="" style={{ width:"100%", display:"block" }} draggable={false}/>
          <canvas ref={cvRef} style={{ position:"absolute", inset:0, width:"100%", height:"100%", opacity:0.5, cursor:"crosshair" }}
            onPointerDown={e=>{ e.preventDefault(); cizili.current=true; try{e.currentTarget.setPointerCapture(e.pointerId);}catch(x){} nokta(e); }}
            onPointerMove={e=>{ if (cizili.current) nokta(e); }} onPointerUp={()=>{ cizili.current=false; }}/>
        </div>
        <div style={{ display:"flex", gap:10, alignItems:"center", margin:"12px 0", flexWrap:"wrap" }}>
          <button onClick={()=>setSilgi(false)} style={{ background:!silgi?"var(--vurgu)":"rgba(255,255,255,0.08)", border:"none", borderRadius:8, padding:"7px 12px", color:"#fff", fontSize:12, cursor:"pointer" }}>🖌 Fırça</button>
          <button onClick={()=>setSilgi(true)} style={{ background:silgi?"var(--vurgu)":"rgba(255,255,255,0.08)", border:"none", borderRadius:8, padding:"7px 12px", color:"#fff", fontSize:12, cursor:"pointer" }}>Silgi</button>
          <input type="range" min="8" max="80" value={kalin} onChange={e=>setKalin(Number(e.target.value))}/>
          <button onClick={()=>{ const c=cvRef.current; c.getContext("2d").clearRect(0,0,c.width,c.height); }} style={{ background:"rgba(255,255,255,0.08)", border:"none", borderRadius:8, padding:"7px 12px", color:"#fff", fontSize:12, cursor:"pointer" }}>Hepsini sil</button>
        </div>
        <div style={{ display:"flex", gap:8 }}>
          <button onClick={onIptal} style={{ flex:1, background:"rgba(255,255,255,0.08)", border:"none", borderRadius:10, padding:12, color:"#f5f5f7", fontSize:13, fontWeight:600, cursor:"pointer" }}>Vazgeç</button>
          <button onClick={()=>onTamam(bos() ? null : cvRef.current)} style={{ flex:2, background:"var(--vurgu)", border:"none", borderRadius:10, padding:12, color:"#fff", fontSize:13, fontWeight:700, cursor:"pointer" }}>Tamam</button>
        </div>
      </div>
    </div>
  );
}

// PDF — blob download (popup yok)
// ═══ ÜRETİM TAKİP YARDIMCILARI ═══

// İki tarih arasındaki SADECE iş günü (Cumartesi/Pazar hariç) milisaniyesini hesaplar
function isGunuSure(baslangic, bitis) {
  if (!baslangic || !bitis || bitis <= baslangic) return 0;
  const GUN_MS = 24 * 60 * 60 * 1000;
  let toplam = 0;
  let cursor = new Date(baslangic);
  const son = new Date(bitis);
  
  while (cursor < son) {
    const gun = cursor.getDay(); // 0=Pazar, 6=Cumartesi
    if (gun !== 0 && gun !== 6) {
      // Bu gün iş günü → günün sonuna kadar veya bitişe kadar say
      const gunSonu = new Date(cursor);
      gunSonu.setHours(24, 0, 0, 0); // ertesi gün 00:00
      const bitisBuGun = son < gunSonu ? son : gunSonu;
      toplam += bitisBuGun - cursor;
    }
    // Sonraki güne geç
    cursor = new Date(cursor);
    cursor.setHours(24, 0, 0, 0);
  }
  return toplam;
}

function sureFmt(ms) {
  if (!ms || ms < 0) return "-";
  const dk = Math.floor(ms / 60000);
  const sa = Math.floor(dk / 60);
  const gun = Math.floor(sa / 24);
  if (gun > 0) return gun + " gün " + (sa % 24) + " sa";
  if (sa > 0) return sa + " sa " + (dk % 60) + " dk";
  return dk + " dk";
}

function siparisDurumHesapla(s) {
  // Tüm kalemlerin mevcut durumlarından en yaygın olanı bul
  const kalemDurumlar = s.kalemDurumlar || {};
  const durumlar = (s.kalemler||[]).map(k => kalemDurumlar[k.id] || k.durum || "baslanmadi").filter(d => d !== "hurda");
  if (!durumlar.length) return "baslanmadi";
  const say = {};
  durumlar.forEach(d => say[d] = (say[d]||0)+1);
  return Object.entries(say).sort((a,b)=>b[1]-a[1])[0][0];
}

function durumSureHesapla(gecmis) {
  // [{durum, tarih}] → her durum için harcanan SADECE İŞ GÜNÜ süresi (hafta sonu hariç)
  const sonuclar = {};
  for (let i = 0; i < gecmis.length; i++) {
    const d = gecmis[i];
    const sonraki = gecmis[i+1];
    const bitis = sonraki ? sonraki.tarih : Date.now();
    const sure = isGunuSure(d.tarih, bitis);
    sonuclar[d.durum] = (sonuclar[d.durum] || 0) + sure;
  }
  return sonuclar;
}

function downloadPDF(html, filename) {
  try {
    // Yöntem 1: Blob ile yeni sekme
    const blob = new Blob([html], { type: "text/html;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.target = "_blank";
    a.rel = "noopener";
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 1000);
  } catch(e) {
    // Yöntem 2: data URI
    try {
      const encoded = "data:text/html;charset=utf-8," + encodeURIComponent(html);
      const a = document.createElement("a");
      a.href = encoded;
      a.target = "_blank";
      a.download = (filename||"pdf") + ".html";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    } catch(e2) {
      alert("PDF acilamadi. Tarayici popup izni verin.");
    }
  }
}

// Sıralama: SADECE koddaki rakam (sayısal)
// Sipariş arama — müşteri adı/kodu, sipariş no (SIP-…), PO, model kodu/adı, açıklama, not, tarih; birden çok kelime hepsi eşleşmeli
function sipAramaUyar(s, qRaw) {
  const q = String(qRaw || "").toLowerCase().trim(); if (!q) return true;
  const tr = (x) => String(x == null ? "" : x).toLowerCase().replace(/İ/g, "i").replace(/ı/g, "i");
  const t = s.tarih ? new Date(s.tarih) : null;
  const po = (String(s.aciklama || "").match(/PO\s*(\d+)/i) || [])[1] || "";
  const hay = tr([s.musteri, s.musKod, s.musEtiket, s.siparisNo, po ? "PO " + po : "", s.aciklama, s.not, s.notlar,
    t ? "SIP-" + t.getFullYear() + "-" + String(s.tarih).slice(-5) : "", t ? t.toLocaleDateString("tr-TR") : "",
    ...(s.kalemler || []).map(k => [k.kod, k.ad, k.model, k.not, k.aciklama].filter(Boolean).join(" "))].filter(Boolean).join(" "));
  return tr(q).split(/\s+/).every(w => hay.includes(w));
}

// Konfirmasyon / Sipariş kalem sıralaması — ortak (ekran + PDF aynı fonksiyonu kullanır)
// mod: "koleksiyon" (varsayılan: koleksiyonlar gruplu, grup içi ekleniş sırası) | "koleksiyonKod" (gruplu, grup içi en yeni koddan eskiye)
//      | "kodTers" (en yeni kod üstte) | "kod" (eskiden yeniye) | "gramAzalan" | "gramArtan"
const KONF_SIRA_SECENEKLERI = [
  { id: "koleksiyon",    l: "Koleksiyona göre (ekleniş sırası)" },
  { id: "koleksiyonKod", l: "Koleksiyona göre · yeni kod → eski" },
  { id: "kodTers",       l: "Kod: yeni → eski" },
  { id: "kod",           l: "Kod: eski → yeni" },
  { id: "gramAzalan",    l: "Gram: yüksek → düşük" },
  { id: "gramArtan",     l: "Gram: düşük → yüksek" },
];
function konfSiralaListe(liste, mod, ayarFn) {
  const arr = [...(liste || [])];
  const kolId = m => m.ki || m.kaynakKi || "_";
  const gramDeger = m => gramDonustur(Number(m.gram)||0, m.refAyar||"14K", (ayarFn ? ayarFn(m) : (m.secilenAyar||m.refAyar)) || "14K", Number(m.tasGram)||0);
  if (mod === "kodTers") return arr.sort((a, b) => dogalSirala(a, b, true));
  if (mod === "kod") return arr.sort((a, b) => dogalSirala(a, b, false));
  if (mod === "gramAzalan") return arr.sort((a, b) => gramDeger(b) - gramDeger(a));
  if (mod === "gramArtan") return arr.sort((a, b) => gramDeger(a) - gramDeger(b));
  // koleksiyon grupları — grup sırası: koleksiyonun listeye ilk girdiği an
  const siraMap = new Map();
  arr.forEach((m, i) => { const k = kolId(m); if (!siraMap.has(k)) siraMap.set(k, i); });
  return arr.sort((a, b) => {
    const fark = siraMap.get(kolId(a)) - siraMap.get(kolId(b));
    if (fark !== 0) return fark;
    return mod === "koleksiyonKod" ? dogalSirala(a, b, true) : 0; // 0 → stabil, ekleniş sırası korunur
  });
}

// Kodun harf ön ekini çıkarır ("ALT185" → "ALT", "01GS21" → "GS", "KDN003" → "KDN")
function kodOnEk(kod) {
  if (!kod) return "—";
  const m = String(kod).match(/([A-Za-zÇĞİÖŞÜçğışöşü]+)/);
  return m ? m[1].toUpperCase() : "—";
}


// CLIP parmak izi dosyası: Storage'da tek JSON (_vektor/v1-<önek>.json)
async function vektorDosyaOku(onek) {
  try {
    const { data } = supabase.storage.from("FOTOLAR").getPublicUrl("_vektor/v1-" + (onek || "msk") + ".json");
    const r = await fetch(data.publicUrl + "?t=" + Date.now());
    if (!r.ok) return null;
    return await r.json();
  } catch { return null; }
}
async function vektorDosyaYaz(onek, obj) {
  const blob = new Blob([JSON.stringify(obj)], { type: "application/json" });
  const { error } = await supabase.storage.from("FOTOLAR").upload("_vektor/v1-" + (onek || "msk") + ".json", blob, { upsert: true, contentType: "application/json", cacheControl: "0" });
  if (error) throw error;
}

// ═══ PDF'TEN SİPARİŞ — ayrıştırıcı (tarayıcı + node'da çalışır) ═══
// İki müşteri formatını okur:
//   1) "excel"  : Excel'den PDF — satır başına: Code (109KP-FB141), Photo, Unit Gram, Quantity, Explanation
//   2) "fabor"  : Fabor işemri — kutu (kart) başına: "NNN # KOD" veya "ModelID : N | Kod : KOD", Adet, Dikkat notu, foto
// Sadece yapıyı çıkarır (metin + foto kutuları). Fotoğrafları kırpma ve model eşleştirme App.jsx tarafında.

const SIP_OZET_ONB = new WeakMap(); // sipariş özeti önbelleği (sipariş nesnesi değişmedikçe yeniden hesaplanmaz)
const PS_KOD_ONEK = /^(\d{1,4}[A-Z]{1,3})-(.+)$/; // 109KP-FB141 → ön ek + bizim kod

function psNorm(s) {
  return String(s || "").toUpperCase().replace(/[\s\-_.,;:]/g, "");
}

function psSayi(s) {
  const n = parseFloat(String(s || "").replace(",", "."));
  return isNaN(n) ? 0 : n;
}

// Metinden olası model kodlarını çıkar: "ALT 104R", "RP 24", "ALT 157 - S", "ALT212-R" ...
// Her aday için uzun → kısa varyantlar döner (örn. ALT104R, ALT104). Hangisinin gerçekten var olduğuna eşleştirme karar verir.
const PS_KARA_ONEK = new Set(["ALTIN","GIBI","GİBİ","PCS","BOY","ADET","SZ","US","CM","MM","GR","RENK","BOYU","NO","KG"]);
function psKodAdaylariCikar(metin) {
  const out = [];
  const t = String(metin || "").toUpperCase();
  const re = /(^|[^A-ZÇĞİÖŞÜ0-9])([A-ZÇĞİÖŞÜ]{1,5})\s?(\d{1,4})(?:\s?-\s?([A-Z0-9]{1,3}))?(?![A-Z0-9])/g;
  let m;
  while ((m = re.exec(t))) {
    if (PS_KARA_ONEK.has(m[2])) continue;
    const taban = m[2] + m[3];
    const tam = m[4] ? taban + "-" + m[4] : taban;
    // "RP 21C" gibi harf eki bitişik yazıldıysa: (?![A-Z0-9]) engeller — ayrıca bitişik harfli hali yakala
    if (!out.includes(tam)) out.push(tam);
    if (!out.includes(taban)) out.push(taban);
  }
  // Bitişik harf ekli: ALT104R, RP24F, RP21C
  const re2 = /(^|[^A-ZÇĞİÖŞÜ0-9])([A-ZÇĞİÖŞÜ]{1,5})\s?(\d{1,4})([A-Z]{1,2})(?![A-Z0-9])/g;
  while ((m = re2.exec(t))) {
    if (PS_KARA_ONEK.has(m[2])) continue;
    const v = m[2] + m[3] + m[4];
    if (!out.includes(v)) out.unshift(v);
  }
  return out;
}

// ═══ Sayfa okuma: metin parçaları + resim kutuları + tablo yatay çizgileri ═══
async function psSayfaOku(pdfjsLib, page) {
  const OPS = pdfjsLib.OPS;
  const vp = page.getViewport({ scale: 1 });
  const W = vp.width, H = vp.height;
  const tc = await page.getTextContent();
  const items = [];
  for (const it of tc.items) {
    const s = (it.str || "").trim();
    if (!s) continue;
    items.push({ s, x: it.transform[4], y: H - it.transform[5], w: it.width || 0 });
  }
  items.sort((a, b) => a.y - b.y || a.x - b.x);

  const opList = await page.getOperatorList();
  const mul = (a, b) => [
    a[0] * b[0] + a[2] * b[1], a[1] * b[0] + a[3] * b[1],
    a[0] * b[2] + a[2] * b[3], a[1] * b[2] + a[3] * b[3],
    a[0] * b[4] + a[2] * b[5] + a[4], a[1] * b[4] + a[3] * b[5] + a[5],
  ];
  const nokta = (m, x, y) => [m[0] * x + m[2] * y + m[4], m[1] * x + m[3] * y + m[5]];
  let ctm = vp.transform.slice();
  const yigin = [];
  const imgs = [];
  const cizgiler = []; // yatay çizgiler: {y, x0, x1}
  const fnArr = opList.fnArray, argArr = opList.argsArray;
  for (let i = 0; i < fnArr.length; i++) {
    const fn = fnArr[i], args = argArr[i];
    if (fn === OPS.save) yigin.push(ctm.slice());
    else if (fn === OPS.restore) { if (yigin.length) ctm = yigin.pop(); }
    else if (fn === OPS.transform) ctm = mul(ctm, args);
    else if (fn === OPS.paintFormXObjectBegin) { yigin.push(ctm.slice()); if (args && args[0]) ctm = mul(ctm, args[0]); }
    else if (fn === OPS.paintFormXObjectEnd) { if (yigin.length) ctm = yigin.pop(); }
    else if (fn === OPS.paintImageXObject || fn === OPS.paintInlineImageXObject || fn === OPS.paintImageMaskXObject || fn === OPS.paintJpegXObject) {
      const p = [nokta(ctm, 0, 0), nokta(ctm, 1, 0), nokta(ctm, 0, 1), nokta(ctm, 1, 1)];
      const xs = p.map(q => q[0]), ys = p.map(q => q[1]);
      const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
      imgs.push({ x0, y0, x1, y1, w: x1 - x0, h: y1 - y0 });
    } else if (fn === OPS.constructPath) {
      const ops = args[0], co = args[1];
      let ci = 0, px = 0, py = 0;
      for (const op of ops) {
        if (op === OPS.moveTo) { px = co[ci]; py = co[ci + 1]; ci += 2; }
        else if (op === OPS.lineTo) {
          const nx = co[ci], ny = co[ci + 1]; ci += 2;
          const a = nokta(ctm, px, py), b = nokta(ctm, nx, ny);
          if (Math.abs(a[1] - b[1]) < 0.6 && Math.abs(a[0] - b[0]) > 150) cizgiler.push({ y: (a[1] + b[1]) / 2, x0: Math.min(a[0], b[0]), x1: Math.max(a[0], b[0]) });
          px = nx; py = ny;
        } else if (op === OPS.rectangle) {
          const rx = co[ci], ry = co[ci + 1], rw = co[ci + 2], rh = co[ci + 3]; ci += 4;
          const a = nokta(ctm, rx, ry), b = nokta(ctm, rx + rw, ry + rh);
          const gen = Math.abs(a[0] - b[0]);
          if (gen > 150) {
            cizgiler.push({ y: a[1], x0: Math.min(a[0], b[0]), x1: Math.max(a[0], b[0]) });
            cizgiler.push({ y: b[1], x0: Math.min(a[0], b[0]), x1: Math.max(a[0], b[0]) });
          }
        } else if (op === OPS.curveTo) ci += 6;
        else if (op === OPS.curveTo2 || op === OPS.curveTo3) ci += 4;
      }
    }
  }
  // Çok küçük (QR, barkod, logo parçası) ve sayfayı kaplayan resimleri ele
  const fotolar = imgs.filter(r => ((r.w >= 38 && r.h >= 38) || (r.w >= 120 && r.h >= 10)) && !(r.w > W * 0.95 && r.h > H * 0.9) && !(Math.abs(r.w - r.h) < 6 && r.w < 62));
  return { W, H, items, imgs: fotolar, cizgiler };
}

// ═══ FABOR İŞEMRİ ═══
const FABOR_ANKRAJ_A = /^(\d{4,8})\s*#\s*(\S.*)$/;
const FABOR_ANKRAJ_B = /ModelID\s*:\s*(\d+)\s*\|\s*Kod\s*:\s*(\S.*)$/i;

function psFaborBaslik(sayfa) {
  const it = sayfa.items;
  const sagindaki = (etiketRe, maxDx = 400) => {
    const e = it.find(x => etiketRe.test(x.s));
    if (!e) return "";
    const s = it.filter(x => Math.abs(x.y - e.y) < 4 && x.x > e.x + 5 && x.x < e.x + maxDx).sort((a, b) => a.x - b.x)[0];
    return s ? s.s : "";
  };
  const ayarM = it.map(x => x.s.match(/^(\d{1,2})\s*K\s*\((\d{3})\)/i)).find(Boolean);
  const tarihler = it.filter(x => /^\d{1,2}\.\d{1,2}\.\d{4}$/.test(x.s)).sort((a, b) => a.x - b.x).map(x => x.s);
  // "Sorumlu" satırında isimden sonra yazılan genel not (örn. "DÜŞÜK AYAR LAK KORUMA YAPALIM")
  let genelNot = "";
  const so = it.find(x => /^Sorumlu$/i.test(x.s));
  if (so) {
    const ayni = it.filter(x => Math.abs(x.y - so.y) < 4 && x.x > so.x + 5).sort((a, b) => a.x - b.x);
    if (ayni.length > 1) genelNot = ayni.slice(1).map(x => x.s).join(" ");
  }
  return {
    referans: sagindaki(/^Referans/i, 260),
    po: sagindaki(/^PO\(Sip/i, 150),
    listeGram: sagindaki(/^Liste Gram/i, 150),
    ayar: ayarM ? ayarM[1] + "K" : "",
    siparisTarihi: tarihler[0] || "",
    teslimTarihi: tarihler[1] || "",
    genelNot,
  };
}

function psFaborKartlar(sayfa, sayfaNo) {
  const { W, H, items, imgs } = sayfa;
  const ankrajlar = [];
  for (const x of items) {
    let m = x.s.match(FABOR_ANKRAJ_B);
    if (m) { ankrajlar.push({ x: x.x, y: x.y, ic: m[2].trim(), id: m[1] }); continue; }
    m = x.s.match(FABOR_ANKRAJ_A);
    if (m) ankrajlar.push({ x: x.x, y: x.y, ic: m[2].trim(), id: m[1] });
  }
  if (!ankrajlar.length) return [];
  ankrajlar.sort((a, b) => a.y - b.y || a.x - b.x);
  // Satırlara grupla
  const satirlar = [];
  for (const a of ankrajlar) {
    const s = satirlar.find(r => Math.abs(r.y - a.y) < 14);
    if (s) s.liste.push(a); else satirlar.push({ y: a.y, liste: [a] });
  }
  satirlar.sort((a, b) => a.y - b.y);
  const kartlar = [];
  satirlar.forEach((sat, si) => {
    const y0 = sat.y - 3;
    const y1 = si + 1 < satirlar.length ? satirlar[si + 1].y - 3 : H;
    sat.liste.sort((a, b) => a.x - b.x);
    sat.liste.forEach((a, ai) => {
      const x0 = ai === 0 ? 0 : a.x - 10;
      const x1 = ai + 1 < sat.liste.length ? sat.liste[ai + 1].x - 10 : W;
      kartlar.push({ ankraj: a, x0, x1, y0, y1, sayfaNo });
    });
  });

  const sonuc = [];
  for (const k of kartlar) {
    const it = items.filter(x => x.x >= k.x0 && x.x < k.x1 && x.y >= k.y0 && x.y < k.y1 && x.s !== "Temsili");
    const sayiMi = s => /^\d+([.,]\d+)?$/.test(s);
    const tamMi = s => /^\d+$/.test(s);

    // ── Adet
    let adet = 0;
    let m;
    for (const x of it) { if ((m = x.s.match(/^Adet\s*:\s*(\d+)/i))) { adet = +m[1]; break; } }
    if (!adet) {
      const e = it.find(x => /^Adet\s*:$/i.test(x.s));
      if (e) { const v = it.filter(x => Math.abs(x.y - e.y) < 4 && x.x > e.x && tamMi(x.s)).sort((a, b) => a.x - b.x)[0]; if (v) adet = +v.s; }
    }
    if (!adet) { // ModelID düzeni: "Adet" etiketi + "46 adet"
      const e = it.find(x => /^Adet$/i.test(x.s));
      if (e) {
        const v = it.filter(x => Math.abs(x.y - e.y) < 5 && x.x > e.x + 5).map(x => ({ x, m: x.s.match(/^(\d+)\s*adet$/i) })).find(q => q.m);
        if (v) adet = +v.m[1];
      }
    }
    if (!adet) { // Tablo düzeni: başlık "Adet" + altındaki satırda tam sayı
      const e = it.find(x => /^Adet$/i.test(x.s));
      if (e) {
        const alt = it.filter(x => x.y > e.y + 3 && x.y < e.y + 70 && tamMi(x.s));
        if (alt.length) {
          const satirY = alt.sort((a, b) => a.y - b.y)[0].y;
          const sat = alt.filter(x => Math.abs(x.y - satirY) < 4);
          sat.sort((a, b) => Math.abs(a.x - e.x) - Math.abs(b.x - e.x));
          adet = +sat[0].s;
        }
      }
    }

    // ── Birim gram
    let gram = 0;
    const istG = it.find(x => /^İst\.?Ağırlık|^İst\.Agirlik/i.test(x.s));
    if (istG) { const v = it.filter(x => Math.abs(x.y - istG.y) < 5 && x.x > istG.x && /gr$/i.test(x.s)).sort((a, b) => a.x - b.x)[0]; if (v) gram = psSayi(v.s); }
    if (!gram) {
      const e = it.find(x => /^Adet\/Gr$/i.test(x.s));
      if (e) {
        const alt = it.filter(x => x.y > e.y + 3 && x.y < e.y + 70 && /^\d+[.,]\d+$/.test(x.s)).sort((a, b) => a.y - b.y);
        if (alt.length) {
          const satirY = alt[0].y;
          const sat = alt.filter(x => Math.abs(x.y - satirY) < 4).sort((a, b) => Math.abs(a.x - e.x) - Math.abs(b.x - e.x));
          gram = psSayi(sat[0].s);
        }
      }
    }
    if (!gram) {
      const e = it.find(x => /^Ağırlık\s*:?$/i.test(x.s));
      if (e) { const v = it.filter(x => Math.abs(x.y - e.y) < 4 && x.x > e.x && sayiMi(x.s)).sort((a, b) => a.x - b.x)[0]; if (v) gram = psSayi(v.s); }
    }

    // ── Boy bilgisi
    let boy = "";
    const boyE = it.find(x => /^Boy\s*:?$/i.test(x.s));
    if (boyE) { const v = it.filter(x => Math.abs(x.y - boyE.y) < 5 && x.x > boyE.x && /\d/.test(x.s)).sort((a, b) => a.x - b.x)[0]; if (v) boy = v.s; }

    // ── Dikkat notu
    let not = "";
    const dE = it.find(x => /^Dikkat/i.test(x.s));
    const tabloUstte = it.some(x => /^Toplam$|^Toplam Gr$/i.test(x.s) && dE && x.y <= dE.y + 12);
    if (dE) {
      const parcalar = [];
      const ilk = dE.s.replace(/^Dikkat\s*:?\s*/i, "");
      let ilkSatir = ilk;
      if (!ilkSatir) { const v = it.filter(x => Math.abs(x.y - dE.y) < 4 && x.x > dE.x && x !== dE).sort((a, b) => a.x - b.x); ilkSatir = v.map(q => q.s.replace(/^:\s*/, "")).join(" "); }
      else { const v = it.filter(x => Math.abs(x.y - dE.y) < 4 && x.x > dE.x + 1 && x !== dE).sort((a, b) => a.x - b.x); if (v.length) ilkSatir += " " + v.map(q => q.s).join(" "); }
      ilkSatir = ilkSatir.replace(/^:\s*/, "").trim();
      if (ilkSatir) parcalar.push(ilkSatir);
      const devam = it.filter(x => x.y > dE.y + 3).sort((a, b) => a.y - b.y || a.x - b.x);
      const etiketRe = /^(ATÖLYE|AtölyeKodu|Adet|İst\.|Sys\.|T\.Ağ|T\.Agirlik|Boy\b|Karakter|Toplam)/i;
      let sonY = null;
      for (const x of devam) {
        if (/^KID\s*:/i.test(x.s) || /^\d{5,7}$/.test(x.s)) break;
        if (etiketRe.test(x.s)) break;
        if (/^\d{3}[A-Z]{3,4}\d{5}$/.test(x.s)) break;
        if (tabloUstte && (sayiMi(x.s) || /^\d{3}[A-Z]{3}\d{5}$/.test(x.s) || /^[A-Z]{2,5}\d{1,4}(-[A-Z0-9]+)?$/.test(x.s))) break;
        if (sonY !== null && x.y - sonY > 40) break;
        sonY = x.y;
        parcalar.push(x.s);
      }
      not = parcalar.join(" ").replace(/\s+/g, " ").trim();
    }

    // ── Atölye kodu değeri (tablo düzeninde "FHP151" gibi bizim koda benzeyen)
    const adayKodlar = [];
    const kodSekli = /^[A-Z]{2,5}\d{1,4}(-[A-Z0-9]+)?$/;
    if (tabloUstte) for (const x of it) if (kodSekli.test(x.s)) adayKodlar.push({ kod: x.s, kaynak: "atölye kodu" });
    const aE = it.find(x => /^AtölyeKodu$/i.test(x.s));
    if (aE) { const v = it.filter(x => Math.abs(x.y - aE.y) < 5 && x.x > aE.x + 5).sort((a, b) => a.x - b.x)[0]; if (v && kodSekli.test(v.s)) adayKodlar.push({ kod: v.s, kaynak: "atölye kodu" }); }
    const notKodlari = psKodAdaylariCikar(not).map(kod => ({ kod, kaynak: "açıklama" }));

    // ── Fotoğraflar (kartın içindeki resimler)
    const kartFoto = imgs.filter(r => {
      const cx = (r.x0 + r.x1) / 2, cy = (r.y0 + r.y1) / 2;
      return cx >= k.x0 && cx < k.x1 && cy >= k.y0 && cy < k.y1;
    }).sort((a, b) => b.w * b.h - a.w * a.h);

    const atolyeKodlari = it.filter(x => /^\d{3}[A-Z]{3}\d{5}$/.test(x.s)).map(x => x.s);
    sonuc.push({
      tip: "fabor",
      sayfaNo,
      disKod: k.ankraj.ic.replace(/\s+/g, " "),
      disId: k.ankraj.id,
      atolyeKodlari,
      kodAdaylari: [...notKodlari, ...adayKodlar],
      adet: adet || 1,
      adetBulundu: !!adet,
      gramBirim: gram,
      boy,
      aciklama: [not, boy ? "Boy: " + boy : ""].filter(Boolean).join(" | "),
      not,
      fotoKutular: kartFoto.map(r => ({ sayfaNo, x0: r.x0, y0: r.y0, x1: r.x1, y1: r.y1 })),
    });
  }
  return sonuc;
}

// ═══ EXCEL PDF ═══
// Satır sınırı yerine yakınlık kullanılır: gram/adet kod ile aynı hizada; açıklama satırları boşluklara göre kümelenip en yakın koda bağlanır;
// resimler merkezine en yakın koda bağlanır.
function psExcelSatirlar(sayfa, sayfaNo, belge) {
  const { W, H, items, imgs } = sayfa;
  const kodlar = items.filter(x => PS_KOD_ONEK.test(x.s));
  if (!kodlar.length) return [];
  kodlar.sort((a, b) => a.y - b.y);
  const kodX = kodlar.map(k => k.x).sort((a, b) => a - b)[Math.floor(kodlar.length / 2)];
  const baslikSozcukler = new Set(["NO.", "NO", "CODE", "PHOTO", "UNIT GRAM", "QUANTITY", "EXPLANATION"]);
  const govde = items.filter(x => !baslikSozcukler.has(x.s.toUpperCase()) && x.y < H - 45 && !PS_KOD_ONEK.test(x.s));
  const medyan = (arr) => arr.length ? arr.slice().sort((a, b) => a - b)[Math.floor(arr.length / 2)] : null;

  // Sütunlar: gram (ondalık), adet (tam sayı, gramın sağında)
  const ondalik = govde.filter(x => /^\d+[.,]\d+$/.test(x.s) && x.x > kodX + 60);
  const gramX = medyan(ondalik.map(x => x.x));
  const tamlar = govde.filter(x => /^\d+$/.test(x.s) && gramX !== null && x.x > gramX + 15);
  const adetX = medyan(tamlar.map(x => x.x));
  if (belge) { if (gramX !== null) belge.gramX = gramX; if (adetX !== null) belge.adetX = adetX; }
  const gX = gramX !== null ? gramX : (belge && belge.gramX);
  const aX = adetX !== null ? adetX : (belge && belge.adetX);

  const enYakin = (y, maxDy) => {
    let en = -1, fark = 1e9;
    kodlar.forEach((k, i) => { const d = Math.abs(k.y - y); if (d < fark) { fark = d; en = i; } });
    return fark <= maxDy ? en : -1;
  };
  const satir = kodlar.map(k => ({ kod: k, gram: 0, adet: 0, acik: [], foto: [] }));

  // gram / adet: kodla aynı hizada
  for (const x of govde) {
    const i = enYakin(x.y, 8);
    if (i < 0) continue;
    if (gX !== null && /^\d+[.,]\d+$/.test(x.s) && Math.abs(x.x - gX) < 40) satir[i].gram = psSayi(x.s);
    else if (aX !== null && /^\d+$/.test(x.s) && Math.abs(x.x - aX) < 30) satir[i].adet = +x.s;
  }
  // açıklama: adet sütununun sağındaki metinler — boşluk > 14pt olunca yeni küme
  if (aX !== null) {
    const acik = govde.filter(x => (x.x + (x.w || 0) / 2) > aX + 45).sort((a, b) => a.y - b.y || a.x - b.x);
    let kume = [];
    const bagla = () => {
      if (!kume.length) return;
      const merkez = (kume[0].y + kume[kume.length - 1].y) / 2;
      const i = enYakin(merkez, 120);
      if (i >= 0) kume.forEach(q => satir[i].acik.push(q.s));
      kume = [];
    };
    for (const x of acik) {
      if (kume.length && x.y - kume[kume.length - 1].y > 14) bagla();
      kume.push(x);
    }
    bagla();
  }
  // resimler: merkezine en yakın koda
  const fotoAday = imgs.filter(r => (r.x0 + r.x1) / 2 > kodX + 40);
  for (const r of fotoAday) {
    const i = enYakin((r.y0 + r.y1) / 2, 110);
    if (i >= 0) satir[i].foto.push(r);
  }

  return satir.map(r => {
    const mm = r.kod.s.match(PS_KOD_ONEK);
    const aciklama = r.acik.join(" ").replace(/\s+/g, " ").trim();
    return {
      tip: "excel",
      sayfaNo,
      disKod: r.kod.s,
      kodAdaylari: [{ kod: mm[2], kaynak: "kod" }, { kod: r.kod.s, kaynak: "tam kod" }],
      adet: r.adet || 1,
      adetBulundu: !!r.adet,
      gramBirim: r.gram,
      aciklama,
      not: aciklama,
      fotoKutular: r.foto.sort((a, b) => a.x0 - b.x0).map(q => ({ sayfaNo, x0: q.x0, y0: q.y0, x1: q.x1, y1: q.y1 })),
    };
  });
}

// ═══ TABLO PDF (3. biçim) — başlık satırı: No | KOD | ADET | RENK | AÇIKLAMA | AD GR | TOPLAM GR | ÜRÜN GÖRSELİ ═══
// Kodlar önek taşımaz (FB170, FB185-5mm). Sütunlar başlık konumlarından, satırlar "No" sütunundaki sayılardan bulunur.
function psTabloBaslikBul(sayfa) {
  const it = sayfa.items;
  const kod = it.find(x => /^KOD$/i.test(x.s));
  if (!kod) return null;
  const ayni = it.filter(x => Math.abs(x.y - kod.y) < 4);
  const bul = (re) => ayni.find(x => re.test(x.s.toUpperCase()));
  const adet = bul(/^ADET$/), gram = bul(/^AD GR$|^BİRİM GR|^GRAM$/), no = bul(/^NO\.?$/);
  if (!adet || !gram) return null;
  const cols = [
    { k: "no", x: no ? no.x : 0, h: no },
    { k: "kod", x: kod.x }, { k: "adet", x: adet.x },
    ...(bul(/^RENK$/) ? [{ k: "renk", x: bul(/^RENK$/).x }] : []),
    ...(bul(/^AÇIKLAMA$|^ACIKLAMA$/) ? [{ k: "acik", x: bul(/^AÇIKLAMA$|^ACIKLAMA$/).x }] : []),
    { k: "gram", x: gram.x },
    ...(bul(/^TOPLAM GR$/) ? [{ k: "top", x: bul(/^TOPLAM GR$/).x }] : []),
    ...(bul(/GÖRSEL|GORSEL|FOTO|PHOTO/) ? [{ k: "gorsel", x: bul(/GÖRSEL|GORSEL|FOTO|PHOTO/).x }] : []),
  ].sort((a, b) => a.x - b.x);
  cols.forEach((c, i) => {
    c.x0 = i === 0 ? -1e9 : (cols[i - 1].x + c.x) / 2;
    c.x1 = i === cols.length - 1 ? 1e9 : (c.x + cols[i + 1].x) / 2;
  });
  return { y: kod.y, cols };
}
function psTabloBaslikBilgi(sayfa) {
  const it = sayfa.items;
  const sag = (re, maxDx = 140) => {
    const e = it.find(x => re.test(x.s.toUpperCase()));
    if (!e) return "";
    const s = it.filter(x => Math.abs(x.y - e.y) < 4 && x.x > e.x + 5 && x.x < e.x + maxDx + 200).sort((a, b) => a.x - b.x)[0];
    return s ? s.s : "";
  };
  const ayarM = (sag(/^AYAR$/) || "").match(/(\d{1,2})/);
  const damga = sag(/^DAMGA$/);
  const dM = (damga || "").match(/(\d{1,2})\s*K/i);
  return {
    referans: sag(/^SİPARİŞ NO$|^SIPARIS NO$/),
    ayar: dM ? dM[1] + "K" : (ayarM ? ayarM[1] + "K" : ""),
    teslimTarihi: sag(/^TESLİM TARİHİ$|^TESLIM TARIHI$/),
    genelNot: "",
  };
}
// basDis: başlığı olmayan devam sayfaları (2. sayfa vb.) için ilk sayfanın sütun konumları
function psTabloSatirlar(sayfa, sayfaNo, basDis) {
  const { H, items, imgs } = sayfa;
  let bs = psTabloBaslikBul(sayfa);
  if (!bs && basDis) bs = { ...basDis, y: -1e9 };
  if (!bs) return [];
  const col = (x) => bs.cols.find(c => x >= c.x0 && x < c.x1);
  const noCol = bs.cols.find(c => c.k === "no") || bs.cols.find(c => c.k === "kod");
  const toplamY = Math.min(1e9, ...items.filter(x => /^TOPLAM\b/i.test(x.s) && x.y > bs.y + 8).map(x => x.y));
  const govde = items.filter(x => x.y > bs.y + 6 && x.y < toplamY - 4);
  const ankraj = govde.filter(x => /^\d{1,3}$/.test(x.s) && col(x.x) && col(x.x).k === "no").sort((a, b) => a.y - b.y);
  if (!ankraj.length) return [];
  const enYakin = (y, maxDy) => { let en = -1, f = 1e9; ankraj.forEach((a, i) => { const d = Math.abs(a.y - y); if (d < f) { f = d; en = i; } }); return f <= maxDy ? en : -1; };
  const satir = ankraj.map(a => ({ y: a.y, kod: "", adet: 0, renk: "", gram: 0, acik: [], foto: [] }));
  for (const x of govde) {
    const c = col(x.x); if (!c || c.k === "no") continue;
    if (c.k === "acik") { const i = enYakin(x.y, 22); if (i >= 0) satir[i].acik.push(x); continue; }
    const i = enYakin(x.y, 8); if (i < 0) continue;
    if (c.k === "kod") satir[i].kod = (satir[i].kod ? satir[i].kod + " " : "") + x.s;
    else if (c.k === "adet" && /^\d+$/.test(x.s)) satir[i].adet = +x.s;
    else if (c.k === "renk") satir[i].renk = (satir[i].renk ? satir[i].renk + " " : "") + x.s;
    else if (c.k === "gram" && /^\d+[.,]?\d*$/.test(x.s)) satir[i].gram = psSayi(x.s);
  }
  const gorsel = bs.cols.find(c => c.k === "gorsel");
  if (gorsel) {
    imgs.filter(r => (r.x0 + r.x1) / 2 > gorsel.x0 && r.y0 > bs.y).forEach(r => { const i = enYakin((r.y0 + r.y1) / 2, 60); if (i >= 0) satir[i].foto.push(r); });
  }
  return satir.filter(r => r.kod).map(r => {
    const kod = r.kod.trim();
    const taban = kod.replace(/[-_]\s*\d+(\.\d+)?\s*(mm|cm)$/i, "");
    const acik = r.acik.sort((a, b) => a.y - b.y || a.x - b.x).map(q => q.s).join(" ").replace(/\s+/g, " ").trim();
    const aday = [{ kod, kaynak: "kod" }]; if (taban !== kod) aday.push({ kod: taban, kaynak: "taban" });
    const metin = [r.renk, acik].filter(Boolean).join(" · ");
    return {
      tip: "excel", sayfaNo, disKod: kod, kodAdaylari: aday,
      adet: r.adet || 1, adetBulundu: !!r.adet, gramBirim: r.gram,
      aciklama: metin, not: metin,
      fotoKutular: r.foto.sort((a, b) => a.x0 - b.x0).map(q => ({ sayfaNo, x0: q.x0, y0: q.y0, x1: q.x1, y1: q.y1 })),
    };
  });
}

// ═══ ANA GİRİŞ ═══
// pdfjsLib: pdf.js kütüphanesi, data: Uint8Array, dönüş: { tip, baslik, kalemler, sayfaSayisi, pdf }
async function psPdfAyristir(pdfjsLib, data) {
  const pdf = await pdfjsLib.getDocument({ data, useSystemFonts: true }).promise;
  const sayfalar = [];
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    sayfalar.push(await psSayfaOku(pdfjsLib, page));
  }
  const faborVar = sayfalar.some(s => s.items.some(x => FABOR_ANKRAJ_A.test(x.s) || FABOR_ANKRAJ_B.test(x.s)));
  let tip = "bilinmiyor", baslik = {}, kalemler = [];
  if (faborVar) {
    tip = "fabor";
    baslik = psFaborBaslik(sayfalar[0]);
    sayfalar.forEach((s, i) => { kalemler.push(...psFaborKartlar(s, i + 1)); });
  } else {
    const belge = {};
    // Sütun konumlarını bulmak için önce tüm sayfaları tara
    sayfalar.forEach((s, i) => { psExcelSatirlar(s, i + 1, belge); });
    sayfalar.forEach((s, i) => { kalemler.push(...psExcelSatirlar(s, i + 1, belge)); });
    if (kalemler.length) tip = "excel";
    else if (sayfalar.some(sf => psTabloBaslikBul(sf))) {
      const basIlk = sayfalar.map(psTabloBaslikBul).find(Boolean);
      sayfalar.forEach((sf, i) => { kalemler.push(...psTabloSatirlar(sf, i + 1, basIlk)); });
      if (kalemler.length) { tip = "excel"; baslik = psTabloBaslikBilgi(sayfalar[0]); }
    }
  }
  kalemler.forEach((k, i) => { k.id = "pk" + (i + 1); });
  return { tip, baslik, kalemler, sayfaSayisi: pdf.numPages, pdf };
}

// ═══ PDF'TEN SİPARİŞ — pdf.js yükleme, foto kırpma, onay ekranı ═══
let _pdfjsYuklenen = null;
function pdfjsYukle() {
  if (typeof window !== "undefined" && window.pdfjsLib) return Promise.resolve(window.pdfjsLib);
  if (_pdfjsYuklenen) return _pdfjsYuklenen;
  _pdfjsYuklenen = new Promise((res, rej) => {
    const s = document.createElement("script");
    s.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
    s.onload = () => {
      try { window.pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js"; res(window.pdfjsLib); }
      catch (e) { _pdfjsYuklenen = null; rej(e); }
    };
    s.onerror = () => { _pdfjsYuklenen = null; rej(new Error("PDF okuyucu yüklenemedi (internet bağlantısını kontrol edin)")); };
    document.head.appendChild(s);
  });
  return _pdfjsYuklenen;
}

// Her sayfayı bir kez çizip, fotoğraf kutularını kırpar → kalem.foto (JPEG data URL), kalem.fotolar
async function psFotolariKirp(pdf, kalemler, ilerle) {
  const OLCEK = 2;
  const sayfaNolar = [...new Set(kalemler.flatMap(k => k.fotoKutular.map(b => b.sayfaNo)))].sort((a, b) => a - b);
  let yapilan = 0;
  for (const no of sayfaNolar) {
    const page = await pdf.getPage(no);
    const vp = page.getViewport({ scale: OLCEK });
    const cv = document.createElement("canvas");
    cv.width = Math.ceil(vp.width); cv.height = Math.ceil(vp.height);
    const ctx = cv.getContext("2d");
    ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, cv.width, cv.height);
    await page.render({ canvasContext: ctx, viewport: vp }).promise;
    for (const k of kalemler) {
      for (const b of k.fotoKutular) {
        if (b.sayfaNo !== no) continue;
        const x = Math.max(0, Math.floor(b.x0 * OLCEK)), y = Math.max(0, Math.floor(b.y0 * OLCEK));
        const w = Math.min(cv.width - x, Math.ceil((b.x1 - b.x0) * OLCEK)), h = Math.min(cv.height - y, Math.ceil((b.y1 - b.y0) * OLCEK));
        if (w < 8 || h < 8) continue;
        const en = Math.min(1, 720 / Math.max(w, h));
        const kc = document.createElement("canvas");
        kc.width = Math.max(1, Math.round(w * en)); kc.height = Math.max(1, Math.round(h * en));
        const kctx = kc.getContext("2d");
        kctx.fillStyle = "#fff"; kctx.fillRect(0, 0, kc.width, kc.height);
        kctx.drawImage(cv, x, y, w, h, 0, 0, kc.width, kc.height);
        b.dataUrl = kc.toDataURL("image/jpeg", 0.85);
        b.alan = (b.x1 - b.x0) * (b.y1 - b.y0);
      }
    }
    cv.width = 0; cv.height = 0;
    yapilan++;
    if (ilerle) ilerle(yapilan, sayfaNolar.length);
  }
  kalemler.forEach(k => {
    const bulunan = k.fotoKutular.filter(b => b.dataUrl).sort((a, b) => b.alan - a.alan);
    k.foto = bulunan.length ? bulunan[0].dataUrl : "";
    k.fotolar = bulunan.map(b => b.dataUrl);
  });
}

// ── Taş rengi: müşteri açıklamasından rengi oku, aynı model ailesinde (ALT209, ALT209-W …) rengi tutan modeli seç ──
const PS_RENKLER = [
  ["BEYAZ", /BEYAZ|WHITE/], ["YESIL", /YESIL|ZUMRUT|GREEN|EMERALD|MALAHIT|MALACHITE/], ["MAVI", /MAVI|BLUE|\bBLU\b|TOPAZ|AKUA/], ["KIRMIZI", /KIRMIZI|RUBY|RUBI|GARNET|RED/],
  ["SIYAH", /SIYAH|ONIKS|ONYX|BLACK/], ["PEMBE", /PEMBE|PINK/], ["MOR", /\bMOR\b|AMETIST|AMETHYST|PURPLE|VIOLET/], ["LACIVERT", /LACIVERT|SAFIR|SAPPHIRE/],
  ["TURKUAZ", /TURKUAZ|TURQUOISE/], ["SARI", /SITRIN|CITRINE/], ["KAHVE", /KAHVE|BROWN|SMOKY/], ["RENKLI", /RENKLI|MULTI|COLORFUL/],
];
const PS_RENK_AD = { BEYAZ: "beyaz", YESIL: "yeşil", MAVI: "mavi", KIRMIZI: "kırmızı", SIYAH: "siyah", PEMBE: "pembe", MOR: "mor", LACIVERT: "lacivert", TURKUAZ: "turkuaz", SARI: "sarı", KAHVE: "kahve", RENKLI: "renkli" };
function psTrBuyuk(t) {
  return String(t || "").replace(/İ/g, "I").replace(/ı/g, "I").toUpperCase()
    .replace(/Ş/g, "S").replace(/Ğ/g, "G").replace(/Ü/g, "U").replace(/Ö/g, "O").replace(/Ç/g, "C").replace(/İ/g, "I");
}
// "beyaz taş", "yeşil taşlı", "taş rengi mavi" → "BEYAZ" / "YESIL" / "MAVI"; yoksa ""
function psNotTasRengi(metin) {
  const t = psTrBuyuk(metin);
  if (!t) return "";
  for (const [k, re] of PS_RENKLER) {
    const r = re.source;
    if (new RegExp("(" + r + ")\\s*(TAS|TASLI|TASIN|TASI|ZIRKON|ZIRCON|STONE)").test(t)) return k;
    if (new RegExp("TAS\\s*(RENGI|RENK)?\\s*[:=\\-]?\\s*(" + r + ")").test(t)) return k;
  }
  return "";
}
// Modelin taş rengi (kayıtlı ad/açıklama/etiket/taş şekli + "-W" son eki)
function psModelTasRengi(m) {
  const bul = (metin) => { const t = psTrBuyuk(metin); const l = []; for (const [k, re] of PS_RENKLER) if (re.test(t)) l.push(k); return l; };
  const sec = (l) => { const ay = l.filter(k => k !== "BEYAZ"); return ay.length ? ay[0] : (l.length ? "BEYAZ" : ""); };
  // 1) Taş kayıtları: boyut/şekil metninde renk yazan taşlar ("8X6 PEMBE", "OCTAGON YEŞİL", "ONYX"); renkli taş varsa o, yoksa beyaz
  const tl = [];
  (Array.isArray(m.taslar) ? m.taslar : []).forEach(t => bul([t && t.sekil, t && t.boyut].filter(Boolean).join(" ")).forEach(k => tl.push(k)));
  const r1 = sec(tl); if (r1) return r1;
  // 2) Ad / açıklama / etiketler
  const r2 = sec(bul([m.ad, m.ac, ...(Array.isArray(m.etiketler) ? m.etiketler : [])].filter(Boolean).join(" "))); if (r2) return r2;
  if (/-W$/.test(psTrBuyuk(m.kod || ""))) return "BEYAZ";
  return "";
}
// Modelin rengi, istenen renkle uyuşuyor mu? (renk yazılmamış model = beyaz)
function psRenkUyar(m, ist) {
  const r = psModelTasRengi(m);
  if (ist === "BEYAZ") return !r || r === "BEYAZ";
  return r === ist || (PS_RENK_YAKIN[ist] || []).includes(r);
}
function psKodTaban(kod) { return psTrBuyuk(kod).replace(/[\s_.]/g, "").replace(/-[A-Z0-9]{1,2}$/, ""); }

// Müşteri notunda birden çok taş rengi varsa ("Colors: White, ruby, emerald, topaz  Each color 3 pcs") sırayla renk listesini döndür
function psNotRenkListesi(metin) {
  const t = psTrBuyuk(metin);
  if (!t || !/COLOU?R|RENK|RENGI|STONE|\bTAS/.test(t)) return [];
  const bulunan = [];
  for (const [k, re] of PS_RENKLER) {
    if (k === "RENKLI") continue;
    const m = new RegExp("\\b(?:" + re.source + ")\\b").exec(t);
    if (m) bulunan.push({ k, i: m.index });
  }
  if (bulunan.length < 2) return [];
  return bulunan.sort((a, b) => a.i - b.i).map(x => x.k);
}
// "each color 3 pcs" / "her renk 3 adet" / "3 pcs each" → 3 (yoksa 0)
function psNotRenkBasiAdet(metin) {
  const t = psTrBuyuk(metin);
  let m = /(?:EACH|PER|HER)\s*(?:COLOU?R|RENK|ONE|BIRI)\D{0,14}?(\d+)/.exec(t);
  if (m) return Number(m[1]) || 0;
  m = /(\d+)\s*(?:PCS|PC|ADET|PIECES?)?\s*(?:EACH|PER\s*COLOU?R|HER\s*RENK|HER\s*BIRI)/.exec(t);
  return m ? (Number(m[1]) || 0) : 0;
}
function psAdetDagit(toplam, n) {
  const t = Math.max(1, Number(toplam) || 1);
  if (n <= 1) return [t];
  const taban = Math.floor(t / n), kalan = t - taban * n;
  return Array.from({ length: n }, (_, i) => Math.max(1, taban + (i < kalan ? 1 : 0)));
}
// Aynı model ailesinden (psKodTaban) her renk için bir model seç
// İki kod aynı model ailesinden mi? FER280 ↔ FER280-Y / FER280Y / FER280B (kısa harfli son ek) — FER28 ↔ FER280 değil
function psAileUyar(kodA, kodB) {
  const a = psKodTaban(kodA), b = psKodTaban(kodB);
  if (!a || !b) return false;
  if (a === b) return true;
  const [kisa, uzun] = a.length <= b.length ? [a, b] : [b, a];
  if (kisa.length < 3 || !/[0-9]$/.test(kisa) || !uzun.startsWith(kisa)) return false;
  return /^[A-Z][A-Z0-9]{0,2}$/.test(uzun.slice(kisa.length));
}
function psAileModelleri(modeller, bulunanKod, adaylar) {
  const aile = []; const gorulen = new Set();
  [...(adaylar || []), ...(modeller || [])].forEach(m => {
    if (!psAileUyar(m.kod, bulunanKod) || aile.some(z => z.id === m.id)) return;
    const nk = psTrBuyuk(m.kod);
    if (gorulen.has(nk)) { const i = aile.findIndex(z => psTrBuyuk(z.kod) === nk); if (!aile[i].foto && m.foto) aile[i] = m; return; }
    gorulen.add(nk); aile.push(m);
  });
  return aile;
}
const PS_RENK_YAKIN = { LACIVERT: ["LACIVERT", "MAVI"], MAVI: ["MAVI", "LACIVERT"] }; // safir: kayıtta mavi/lacivert olabilir
function psRenkAilesi(modeller, bulunanKod, adaylar, renkler) {
  const aile = psAileModelleri(modeller, bulunanKod, adaylar);
  const tam = psTrBuyuk(bulunanKod);
  const secimler = [], eksik = [];
  renkler.forEach(r => {
    const kabul = PS_RENK_YAKIN[r] || [r];
    let uyan = aile.filter(m => kabul.includes(psModelTasRengi(m))).sort((x, y) => kabul.indexOf(psModelTasRengi(x)) - kabul.indexOf(psModelTasRengi(y)));
    if (!uyan.length && r === "BEYAZ") uyan = aile.filter(m => psTrBuyuk(m.kod) === tam && !psModelTasRengi(m));
    uyan = uyan.filter(m => !secimler.some(x => x.m.id === m.id));
    uyan.sort((x, y) => (kabul.indexOf(psModelTasRengi(x)) - kabul.indexOf(psModelTasRengi(y))) || (psTrBuyuk(y.kod) === tam ? 1 : 0) - (psTrBuyuk(x.kod) === tam ? 1 : 0) || (y.foto ? 1 : 0) - (x.foto ? 1 : 0) || psTrBuyuk(x.kod).localeCompare(psTrBuyuk(y.kod)));
    if (uyan.length) secimler.push({ renk: r, m: uyan[0] }); else eksik.push(r);
  });
  return { secimler, eksik };
}

// ── SET modeli: müşteri tek parça (ör. sadece kolye) istiyorsa setin ilgili parçasını bul ──
const PS_PARCA_KOKLERI = [["yuzuk", "YUZ"], ["kolye", "KOLYE"], ["kolye", "PENDANT"], ["kolye", "PANDANTIF"], ["kolye", "SARKIT"], ["kupe", "KUPE"], ["bilezik", "BILEZIK"], ["bileklik", "BILEKLIK"]];
const PS_PARCA_AD = { yuzuk: "yüzük", kolye: "kolye", kupe: "küpe", bilezik: "bilezik", bileklik: "bileklik" };
function psParcaGrubu(kategori) { return kategori === "pendant" ? "kolye" : kategori; }
// not → { digeri: "yuzuk" | "", dogrudan: ["kolye"] }  ("RP24D YÜZÜĞÜYLE MATCH OLACAK" → digeri = yüzük, yani bu kalem yüzük DEĞİL)
function psNotParcaIpucu(metin) {
  const t = psTrBuyuk(metin);
  let digeri = "";
  for (const [g, kok] of PS_PARCA_KOKLERI) {
    if (new RegExp("\\b" + kok + "\\w*\\s+(?:ILE\\s+)?(?:MATCH|TAKIM|SET\\b|UYUM|UYUS|ESLES)").test(t)) { digeri = g; break; }
  }
  const dogrudan = [];
  if (!digeri) for (const [g, kok] of PS_PARCA_KOKLERI) if (new RegExp("\\b" + kok).test(t) && !dogrudan.includes(g)) dogrudan.push(g);
  return { digeri, dogrudan };
}

// ── FOTOĞRAF PARMAK İZİ (CLIP — tarayıcıda çalışır, sunucu gerekmez) ──
// Katalog fotoğraflarının parmak izleri Storage'da tek dosyada (_vektor/v1-<önek>.json) saklanır; PDF'teki fotoğraf da aynı modelle
// parmak izine çevrilir ve katalogdakilere en çok benzeyenler önerilir.
const PS_CLIP_MODEL = "Xenova/clip-vit-base-patch32";
const PS_VQ = 905;               // int8 nicemleme çarpanı (cos = nokta çarpım / PS_VQ²)
const PS_VQ2 = PS_VQ * PS_VQ;
let _clipHazir = null;
let psIndeksDepo = null;         // { ids, fotos, dim, mat:Int8Array }
function clipYukle(ilerle) {
  if (_clipHazir) return _clipHazir;
  _clipHazir = (async () => {
    const TURL = "https://cdn.jsdelivr.net/npm/@xenova/transformers@2.17.2/dist/transformers.min.js";
    const T = await import(/* @vite-ignore */ TURL);
    T.env.allowLocalModels = false;
    T.env.useBrowserCache = true;
    const cb = ilerle ? (p) => { if (p && p.status === "progress") ilerle(Math.round(p.progress || 0)); } : undefined;
    const processor = await T.AutoProcessor.from_pretrained(PS_CLIP_MODEL, { progress_callback: cb });
    const model = await T.CLIPVisionModelWithProjection.from_pretrained(PS_CLIP_MODEL, { quantized: true, progress_callback: cb });
    return { T, processor, model };
  })().catch(e => { _clipHazir = null; throw e; });
  return _clipHazir;
}
// Fotoğrafı (URL veya data URL) beyaz zeminli kareye oturtur — dar/uzun ürünler (bileklik) kırpılmasın
async function psKareBlob(kaynak) {
  const r = await fetch(kaynak, { mode: "cors" });
  if (!r.ok) throw new Error("foto indirilemedi (" + r.status + ")");
  const bmp = await createImageBitmap(await r.blob());
  const S = 224, cv = document.createElement("canvas");
  cv.width = cv.height = S;
  const ctx = cv.getContext("2d");
  ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, S, S);
  const oran = Math.min(S * 0.94 / bmp.width, S * 0.94 / bmp.height);
  const w = bmp.width * oran, h = bmp.height * oran;
  ctx.drawImage(bmp, (S - w) / 2, (S - h) / 2, w, h);
  if (bmp.close) bmp.close();
  return await new Promise((res, rej) => cv.toBlob(b => b ? res(b) : rej(new Error("görüntü hazırlanamadı")), "image/png"));
}
async function clipVektorBlob(blob, ilerle) {
  const { T, processor, model } = await clipYukle(ilerle);
  const img = await T.RawImage.fromBlob(blob);
  const inputs = await processor(img);
  const { image_embeds } = await model(inputs);
  const v = image_embeds.data;
  let n = 0; for (let i = 0; i < v.length; i++) n += v[i] * v[i];
  n = Math.sqrt(n) || 1;
  const q = new Int8Array(v.length);
  for (let i = 0; i < v.length; i++) q[i] = Math.max(-127, Math.min(127, Math.round(v[i] / n * PS_VQ)));
  return q;
}
function psIndeksCoz(j) {
  if (!j || !j.data || !Array.isArray(j.ids)) return null;
  const bin = atob(j.data);
  const mat = new Int8Array(bin.length);
  for (let i = 0; i < bin.length; i++) mat[i] = (bin.charCodeAt(i) << 24) >> 24;
  if (mat.length !== j.ids.length * j.dim) return null;
  return { ids: j.ids, fotos: j.fotos || [], dim: j.dim, mat };
}
function psIndeksKodla(ids, fotos, dim, mat) {
  const u = new Uint8Array(mat.buffer, mat.byteOffset, mat.byteLength);
  let bin = "";
  for (let i = 0; i < u.length; i += 0x8000) bin += String.fromCharCode.apply(null, u.subarray(i, i + 0x8000));
  return { v: 1, dim, q: PS_VQ, ids, fotos, data: btoa(bin) };
}
// Fotoğrafı olan ama indekste olmayan (veya fotoğrafı değişmiş) modeller
function psIndeksEksikler(modeller) {
  const D = psIndeksDepo;
  const var_ = new Map();
  if (D) D.ids.forEach((id, i) => var_.set(id, D.fotos[i]));
  return (modeller || []).filter(m => m.foto && /^https?:/.test(m.foto) && var_.get(m.id) !== m.foto);
}
async function psIndeksKur(modeller, onek, iptal, ilerle) {
  const D = psIndeksDepo;
  const dim = 512;
  const harita = new Map();
  if (D && D.dim === dim) D.ids.forEach((id, i) => harita.set(id, { foto: D.fotos[i], vec: D.mat.subarray(i * dim, (i + 1) * dim) }));
  const eksik = psIndeksEksikler(modeller);
  const gecerli = new Set((modeller || []).filter(m => m.foto).map(m => m.id));
  const kaydet = async () => {
    const ids = [], fotos = [];
    harita.forEach((e, id) => { if (gecerli.has(id)) { ids.push(id); fotos.push(e.foto); } });
    const mat = new Int8Array(ids.length * dim);
    ids.forEach((id, i) => mat.set(harita.get(id).vec, i * dim));
    await vektorDosyaYaz(onek, psIndeksKodla(ids, fotos, dim, mat));
    psIndeksDepo = { ids, fotos, dim, mat };
  };
  const ON = 4, bp = new Map();
  const hazirla = i => { if (i < eksik.length && !bp.has(i)) { const p = psKareBlob(eksik[i].foto); p.catch(() => {}); bp.set(i, p); } };
  for (let i = 0; i < ON; i++) hazirla(i);
  let bitti = 0, hata = 0, sonKayit = 0;
  for (let i = 0; i < eksik.length; i++) {
    if (iptal.current) break;
    hazirla(i + ON);
    try {
      const blob = await bp.get(i);
      const vec = await clipVektorBlob(blob);
      harita.set(eksik[i].id, { foto: eksik[i].foto, vec });
    } catch (e) { hata++; if (hata <= 3) console.warn("indeks hata:", eksik[i].kod, e && e.message); }
    bp.delete(i);
    bitti++;
    ilerle(bitti, eksik.length, hata);
    if (bitti - sonKayit >= 250) { await kaydet(); sonKayit = bitti; }
  }
  if (bitti > sonKayit || eksik.length === 0) await kaydet();
  return { bitti, hata, toplam: eksik.length };
}
// q: Int8Array parmak izi → en benzer n model (aynı kodlu kopyalar tek sayılır)
function psBenzerBul(q, modeller, n) {
  const D = psIndeksDepo;
  if (!D || !D.ids.length) return [];
  const dim = D.dim, mat = D.mat, sk = new Float32Array(D.ids.length);
  for (let r = 0; r < D.ids.length; r++) { let d = 0; const o = r * dim; for (let k = 0; k < dim; k++) d += mat[o + k] * q[k]; sk[r] = d / PS_VQ2; }
  const sira = Array.from(sk.keys()).sort((a, b) => sk[b] - sk[a]);
  const mh = new Map((modeller || []).map(m => [m.id, m]));
  const gorulen = new Set(), sonuc = [];
  for (const r of sira) {
    const m = mh.get(D.ids[r]);
    if (!m) continue;
    const nk = psNorm(m.kod);
    if (gorulen.has(nk)) continue;
    gorulen.add(nk);
    sonuc.push({ m, skor: sk[r] });
    if (sonuc.length >= n) break;
  }
  return sonuc;
}

// Bekleyen kartlarda saklanacak müşteri fotoğrafını küçültür (taslak kaydı şişmesin)
async function psKucukFoto(src, maks = 360) {
  try {
    const img = await new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src; });
    const o = Math.min(1, maks / Math.max(img.width, img.height));
    const cv = document.createElement("canvas");
    cv.width = Math.max(1, Math.round(img.width * o)); cv.height = Math.max(1, Math.round(img.height * o));
    const ctx = cv.getContext("2d"); ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, cv.width, cv.height); ctx.drawImage(img, 0, 0, cv.width, cv.height);
    return cv.toDataURL("image/jpeg", 0.72);
  } catch { return src; }
}

function psKategoriTahmin(k) {
  const t = ((k.aciklama || "") + " " + (k.disKod || "")).toUpperCase();
  if (/BRACELET|BİLEKLİK|BILEKLIK/.test(t)) return "bileklik";
  if (/NECKLACE|KOLYE|PENDANT|KULON|\bCHAIN\b/.test(t)) return "kolye";
  if (/EARRING|KÜPE|KUPE/.test(t)) return "kupe";
  if (/\bUS-?1\b|\bUS\b|MALAFA|YÜZÜK|YUZUK|\bRING\b|\bSIZE\b/.test(t)) return "yuzuk";
  return "diger";
}

function psTemaAcik(T) {
  const h = String((T && T.bg2) || "").match(/^#([0-9a-f]{6})$/i);
  if (h) { const n = parseInt(h[1], 16); return (0.299 * (n >> 16) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255)) > 150; }
  return !!T && T.id === "beyaz";
}
