          adaylar: sirali, secimId: secId, bulunanKod, renkUyari, ekler, adetBasi, adetPdf: k.adet || 1,
          adet: adet0, not: k.aciklama || "",
          dahil: true, // tüm satırlar hazır gelir; işaretini kaldırarak çıkarırsın
